from collections import defaultdict, deque
import random

def compute_girth(adj, n):
    min_cycle = float('inf')
    for start in range(n):
        dist = {start: 0}
        parent = {start: -1}
        q = deque([start])
        while q:
            v = q.popleft()
            if dist[v] >= min_cycle - 1:
                continue
            for nb in adj[v]:
                if nb not in dist:
                    dist[nb] = dist[v] + 1
                    parent[nb] = v
                    q.append(nb)
                elif nb != parent[v]:
                    cycle_len = dist[v] + dist[nb] + 1
                    if cycle_len < min_cycle:
                        min_cycle = cycle_len
    return min_cycle

def random_regular_graph(n, d):
    """Generate a random d-regular graph using configuration model"""
    if (n * d) % 2 != 0:
        return None

    stubs = []
    for v in range(n):
        stubs.extend([v] * d)

    for attempt in range(100):
        random.shuffle(stubs)
        edges = set()
        ok = True
        for i in range(0, len(stubs), 2):
            u, v = stubs[i], stubs[i+1]
            if u == v:
                ok = False
                break
            edge = (min(u, v), max(u, v))
            if edge in edges:
                ok = False
                break
            edges.add(edge)

        if ok:
            return list(edges)
    return None

def improve_girth(edges, n, iterations=5000):
    adj = defaultdict(set)
    for u, v in edges:
        adj[u].add(v)
        adj[v].add(u)

    current_girth = compute_girth(adj, n)
    best_edges = edges[:]
    best_girth = current_girth

    for it in range(iterations):
        # Pick two random edges
        i, j = random.sample(range(len(edges)), 2)
        a, b = edges[i]
        c, d = edges[j]

        # Try both possible swaps
        for swap in [(a,c,b,d), (a,d,b,c)]:
            u1, v1, u2, v2 = swap
            if len({u1, v1, u2, v2}) < 4:
                continue

            new_edges = edges[:]
            new_edges[i] = (min(u1, v1), max(u1, v1))
            new_edges[j] = (min(u2, v2), max(u2, v2))

            new_adj = defaultdict(set)
            for u, v in new_edges:
                new_adj[u].add(v)
                new_adj[v].add(u)

            new_girth = compute_girth(new_adj, n)

            if new_girth > best_girth:
                best_edges = new_edges[:]
                best_girth = new_girth
                edges = new_edges
                adj = new_adj
                break
            elif new_girth == best_girth and random.random() < 0.05:
                edges = new_edges
                adj = new_adj
                break

    return best_edges, best_girth

